// Shared SVG chart primitives for the isolated prototype; no production data access.
export const formatNumber=value=>new Intl.NumberFormat('zh-CN').format(value);
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const color=i=>`var(--series-${i+1})`;

export function lineChart({id,labels,series,height=250,area=false,compact=false}) {
  const width=compact?480:900,pad={left:54,right:20,top:18,bottom:34};
  const values=series.flatMap(s=>s.values).filter(v=>v!==null);
  const min=Math.min(0,...values),max=Math.max(1,...values),step=Math.pow(10,Math.floor(Math.log10(max)))/5,ceiling=Math.ceil(max/step)*step,lower=Math.floor(min/step)*step;
  const x=i=>pad.left+i*(width-pad.left-pad.right)/Math.max(1,labels.length-1);
  const y=v=>height-pad.bottom-(v-lower)/(ceiling-lower)*(height-pad.top-pad.bottom);
  const grid=Array.from({length:6},(_,i)=>{const v=lower+(ceiling-lower)*i/5;return `<line x1="${pad.left}" x2="${width-pad.right}" y1="${y(v)}" y2="${y(v)}" class="chart-gridline"/><text x="${pad.left-12}" y="${y(v)+4}" text-anchor="end" class="chart-label">${v>=1000?Number((v/1000).toFixed(1))+'k':Math.round(v)}</text>`}).join('');
  const lines=series.map(s=>{const parts=[];let part=[];s.values.forEach((v,i)=>{if(v===null){if(part.length)parts.push(part);part=[]}else part.push([x(i),y(v)])});if(part.length)parts.push(part);return parts.map(points=>{if(points.length===1)return `<circle cx="${points[0][0]}" cy="${points[0][1]}" r="3" fill="${color(s.color)}"/>`;const d=points.map(([a,b],i)=>`${i?'L':'M'}${a},${b}`).join(' ');return `${area?`<path d="${d} L${points.at(-1)[0]},${y(0)} L${points[0][0]},${y(0)} Z" fill="${color(s.color)}" opacity=".10"/>`:''}<path d="${d}" fill="none" stroke="${color(s.color)}" stroke-width="2" vector-effect="non-scaling-stroke" ${s.dashed?'stroke-dasharray="5 5"':''}/>`}).join('')}).join('');
  const tickEvery=Math.max(1,Math.ceil(labels.length/10));const axis=labels.map((label,i)=>i%tickEvery===0||i===labels.length-1?`<text x="${x(i)}" y="${height-8}" text-anchor="middle" class="chart-label axis-x" data-tick="${i}">${escape(label)}</text>`:'').join('');
  const hit=labels.map((label,i)=>`<rect x="${x(i)-Math.max(12,(width-pad.left-pad.right)/labels.length/2)}" y="${pad.top}" width="${Math.max(24,(width-pad.left-pad.right)/labels.length)}" height="${height-pad.top-pad.bottom}" fill="transparent" tabindex="0" role="button" data-chart-point="${i}" data-chart-id="${id}" aria-label="${escape(label)}：${escape(series.map(s=>s.name+' '+(s.values[i]===null?'暂无数据':formatNumber(s.values[i]))).join('，'))}"/>`).join('');
  return `<div class="line-chart" data-line-chart="${id}"><svg class="chart-svg" viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" role="group" aria-label="${series.map(s=>escape(s.name)).join('与')}趋势">${grid}${lines}${axis}${hit}</svg><div class="chart-tooltip" role="status" aria-live="polite" hidden></div></div>`;
}

export function verticalBars({values,labels=[],title='区间柱状图'}) {
  const max=Math.max(1,...values),width=420,height=132,gap=6,bw=(width-gap*(values.length-1))/values.length;
  return `<svg class="bars-svg" viewBox="0 0 ${width} ${height}" role="group" aria-label="${title}">${values.map((v,i)=>v===null?`<rect x="${i*(bw+gap)}" y="${height-20}" width="${bw}" height="3" fill="none" stroke="var(--quiet)" tabindex="0" data-chart-detail="${escape(labels[i]||'区间 '+(i+1))}：暂无数据" role="button" aria-label="${escape(labels[i]||'区间 '+(i+1))} 暂无数据"/>`:`<rect x="${i*(bw+gap)}" y="${height-18-v/max*(height-24)}" width="${bw}" height="${v/max*(height-24)}" rx="1.5" fill="var(--series-1)" opacity="${.5+(i%5)/10}" tabindex="0" data-chart-detail="${escape(labels[i]||'区间 '+(i+1))}：${formatNumber(v)}" role="button" aria-label="${escape(labels[i]||'区间 '+(i+1))} ${formatNumber(v)}"/>`).join('')}<line x1="0" x2="${width}" y1="${height-17}" y2="${height-17}" class="chart-gridline"/></svg>`;
}

export function donutChart(items,{title='来源分布',center='',subtitle='',small=false,callouts=false}={}) {
  const total=items.reduce((n,a)=>n+a.value,0),radius=76,circumference=2*Math.PI*radius;let offset=0;
  const segments=items.map((item,i)=>{const length=item.value/total*circumference,start=offset;offset+=length;return `<circle cx="125" cy="125" r="${radius}" fill="none" stroke="${color(i)}" stroke-width="${small?33:36}" stroke-dasharray="${Math.max(0,length-3)} ${circumference}" stroke-dashoffset="${-start}" transform="rotate(-90 125 125)" tabindex="0" role="button" data-chart-detail="${escape(item.label)}：${formatNumber(item.value)}（${(item.value/total*100).toFixed(1)}%）" aria-label="${escape(item.label)} ${formatNumber(item.value)} ${Math.round(item.value/total*100)}%"/>`}).join('');
  if(callouts){let cursor=0;const positions=[[288,150],[46,232],[40,105],[75,52],[250,46]];const annotations=items.map((item,i)=>{const angle=(cursor+item.value/total/2)*2*Math.PI-Math.PI/2;cursor+=item.value/total;const x=125+94*Math.cos(angle)+45,y=125+94*Math.sin(angle)+25;const [tx,ty]=positions[i];const right=tx>170;return `<path d="M${x},${y} L${right?tx-8:tx+8},${ty}" fill="none" stroke="var(--quiet)" stroke-width=".6"/><text x="${tx}" y="${ty-7}" text-anchor="${right?'start':'end'}" class="chart-label callout-label">${escape(item.label)}</text><text x="${tx}" y="${ty+9}" text-anchor="${right?'start':'end'}" class="callout-value">${formatNumber(item.value)}</text>`}).join('');return `<div class="donut-chart with-callouts"><svg viewBox="0 0 340 310" class="donut-svg" role="group" aria-label="${title}"><g transform="translate(45 25)"><circle cx="125" cy="125" r="${radius}" fill="none" stroke="var(--surface-3)" stroke-width="36"/>${segments}<text x="125" y="124" text-anchor="middle" class="donut-total">${escape(center||formatNumber(total))}</text><text x="125" y="146" text-anchor="middle" class="chart-label">${escape(subtitle||'总计')}</text></g>${annotations}</svg><div class="chart-source-note">点击扇区查看占比与观察值</div></div>`}
  return `<div class="donut-chart"><svg viewBox="0 0 250 250" class="donut-svg" role="group" aria-label="${title}"><circle cx="125" cy="125" r="${radius}" fill="none" stroke="var(--surface-3)" stroke-width="36"/>${segments}<text x="125" y="124" text-anchor="middle" class="donut-total">${escape(center||formatNumber(total))}</text><text x="125" y="146" text-anchor="middle" class="chart-label">${escape(subtitle||'总计')}</text></svg><div class="donut-legend ${small?'device-legend':''}">${items.map((item,i)=>`<button data-chart-detail="${escape(item.label)}：${formatNumber(item.value)}（${(item.value/total*100).toFixed(1)}%）"><i style="background:${color(i)}"></i><span>${escape(item.label)}</span><strong>${(item.value/total*100).toFixed(1)}%</strong></button>`).join('')}</div></div>`;
}

export function heatmap() {
  return `<div class="heatmap" role="group" aria-label="一周各时段观察热力图"><div class="heatmap-grid">${Array.from({length:24},(_,hour)=>Array.from({length:7},(_,day)=>{const level=Math.min(5,Math.max(0,Math.round((Math.sin((hour-7)/5)+1)*1.8+(day%3)*.6)));const value=level*43+day*9;return `<button class="heat-cell heat-${level}" data-chart-detail="周${['日','一','二','三','四','五','六'][day]} ${hour}:00：${value} 次观察（示例）" aria-label="周${['日','一','二','三','四','五','六'][day]} ${hour}点 ${value}次观察"></button>`}).join('')).join('')}</div><div class="heat-hours"><span>00:00</span><span>06:00</span><span>12:00</span><span>18:00</span><span>23:00</span></div><div class="heat-days">${['日','一','二','三','四','五','六'].map(t=>`<span>${t}</span>`).join('')}</div><div class="heat-scale"><span>少</span>${Array.from({length:6},(_,i)=>`<i class="heat-${i}"></i>`).join('')}<span>多</span></div></div>`;
}

export function cohortTable() {
  const rows=['全部样本','09.01–09.07','09.08–09.14','09.15–09.21','09.22–09.28','09.29–10.05'];
  return `<div class="cohort-table" role="region" aria-label="分组留存热力矩阵" tabindex="0"><table><thead><tr><th>观察周</th>${[0,1,2,3,4,5].map(n=>`<th>${n}</th>`).join('')}</tr></thead><tbody>${rows.map((label,row)=>`<tr><th>${label}</th>${Array.from({length:6},(_,col)=>{if(row>0&&col>6-row)return '<td class="cohort-missing"><span aria-label="尚无该周期数据">—</span></td>';const value=col===0?100:Math.max(1,18-col*2.8-row*.7).toFixed(1);return `<td><button class="cohort-cell heat-${col===0?5:Math.max(1,5-col)}" data-chart-detail="${label} / 第 ${col} 周：${value}%（示例留存）" aria-label="${label} 第${col}周 留存${value}%">${value}%</button></td>`}).join('')}</tr>`).join('')}</tbody></table></div>`;
}

export function stackedBar(items) {
  const total=items.reduce((n,a)=>n+a.value,0);return `<div class="stacked-bar" role="group" aria-label="内容占比堆叠条形图">${items.map((a,i)=>`<button style="flex:${a.value};background:${color(i)}" data-chart-detail="${escape(a.label)}：${formatNumber(a.value)}（${(a.value/total*100).toFixed(1)}%）" aria-label="${escape(a.label)} ${(a.value/total*100).toFixed(1)}%"></button>`).join('')}</div>`;
}
